
<template>

<div class="container"> <div class="card"> <h2>公告</h2> <ul> <li v-for="a in announcements" :key="a.id"> <strong>{{ a.title }}</strong> <p class="tip">{{ a.content }}</p> </li> </ul> <p v-if="!announcements.length" class="tip">暂无公告</p> </div> <div class="card"> <h2>最新活动</h2> <div v-for="act in activities" :key="act.id" class="activity"> <div> <strong>{{ act.title }}</strong> <p class="tip">{{ act.description }}</p> <p class="tip">奖励：{{ act.reward }}</p> </div> <button @click="claim(act.id)" :disabled="claiming === act.id"> {{ claiming === act.id ? '领取中...' : '领取礼包' }} </button> </div> <p v-if="!activities.length" class="tip">暂无活动</p> </div> </div> </template><script setup> import { ref, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { contentApi } from '../api'; import { useUserStore } from '../stores/user'; const announcements = ref([]); const activities = ref([]); const claiming = ref(null); const store = useUserStore(); const router = useRouter(); async function load() { const [a, b] = await Promise.all([ contentApi.announcements(), contentApi.activities() ]); announcements.value = a.data; activities.value = b.data; } async function claim(id) { if (!store.isLoggedIn) { router.push({ path: '/login', query: { redirect: '/home' } }); return; } claiming.value = id; try { const res = await contentApi.claim(id); alert(`领取成功：${res.data.reward}`); } catch (e) { alert(e.message || '领取失败'); } finally { claiming.value = null; } } onMounted(load); </script><style scoped> .activity { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid #f0f0f0; } .activity:last-child { border-bottom: none; } </style>
